// Record-anchor + dispute contract (BLOCKCHAIN_ECONOMICS §7, §11).
// Permissionless keepers anchor a per-epoch Merkle root (chained to the previous
// root, gated by a stake-weighted threshold). Anyone can open a bonded dispute
// with a Merkle inclusion proof; an authoritative committee resolves it
// (upheld => challenger bond returned + slashing happens via the StakeVault
// slasher path; rejected => bond forfeited, anti-griefing).
//
// Only PAID jobs are anchored. Free jobs keep their signed receipts purely
// off-chain and are never written here (§8.2).

import "anchor_types"
import "common"

contract RecordAnchor {
    storage: AnchorStorage
    incomingMessages: AllowedMessageToAnchor
}

type AllowedMessageToAnchor =
    | AnchorSubmitRoot
    | AnchorOpenDispute
    | AnchorResolveDispute
    | AnchorUpgradeCode

// A1 bounce-safety: a bond refund that the recipient could not accept bounces
// back here. Recover the `disputeId` (first 32 bits after the 0xFFFFFFFF prefix
// and the op tag) and RE-OPEN the dispute (status → 0) so the authority can
// re-resolve it. The bounced TON returns to this (non-custodial) contract, so the
// bond is never lost and accounting is restored.
fun onBouncedMessage(in: InMessageBounced) {
    var body = in.bouncedBody;
    body.skipBouncedPrefix();          // drop 0xFFFFFFFF
    val op = body.loadUint(32);
    if (op == OP_ANCHOR_BOND_REFUND) {
        val disputeId = body.loadUint(32) as uint32;
        var storage = lazy AnchorStorage.load();
        val found = storage.disputes.get(disputeId);
        if (found.isFound) {
            var dispute = found.loadValue();
            dispute.status = 0;        // re-open: the verdict can be re-applied
            storage.disputes.set(disputeId, dispute);
            storage.save();
        }
    }
}

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToAnchor.fromSlice(in.body);

    match (msg) {
        AnchorSubmitRoot => {
            var storage = lazy AnchorStorage.load();
            val cfg = storage.config.load();

            // A3: gate submission to the authorized keeper (NOT permissionless).
            // `stakeWeight` is still an unverified number — see AnchorConfig.keeper
            // for the documented residual assumption.
            val auth = cfg.auth.load();
            assert (in.senderAddress == auth.keeper) throw ErrCode.NOT_ANCHOR_KEEPER;
            // A5: enforce the dispute-bond floor at first use (the config is set at
            // deploy and has no on-chain setter, so genesis is the validation point).
            validateAnchorConfig(cfg);
            // A6: refuse an empty / all-zero root. A zero root would otherwise pass
            // the genesis prevRoot==0 chain check and anchor a meaningless epoch.
            assert (msg.root != 0) throw ErrCode.ZERO_ROOT;
            // Epochs advance monotonically; each root chains to the previous one.
            assert (msg.epoch == storage.currentEpoch + 1) throw ErrCode.EPOCH_REGRESSION;
            assert (msg.prevRoot == storage.lastRoot) throw ErrCode.BAD_PREV_ROOT;
            // Stake-weighted acceptance: the aggregate weight backing the root
            // must clear the threshold (anchoring is not a trust bottleneck).
            assert (msg.stakeWeight >= cfg.minStakeWeight) throw ErrCode.INSUFFICIENT_ANCHOR_STAKE;

            storage.currentEpoch = msg.epoch;
            storage.lastRoot = msg.root;
            // A2: record the authoritative per-epoch root for later dispute
            // verification (proofs verify against THIS, not an attacker root).
            storage.roots.set(msg.epoch, msg.root);
            storage.save();
            // (A small keeper reward could be paid here from accumulated fees.)
        }

        AnchorOpenDispute => {
            var storage = lazy AnchorStorage.load();
            val cfg = storage.config.load();
            assert (in.valueCoins >= cfg.disputeBondMin) throw ErrCode.DISPUTE_BOND_TOO_LOW;

            // A2: look up the STORED root for this epoch. An epoch that was never
            // anchored cannot be disputed (rejects forged / unknown-epoch claims).
            val rootFound = storage.roots.get(msg.epoch);
            assert (rootFound.isFound) throw ErrCode.UNKNOWN_EPOCH;
            val anchoredRoot = rootFound.loadValue();

            // The inclusion proof must reproduce the contract's OWN anchored root
            // (A2) using the leaf-domain-separated fold (A7). Both the root and the
            // leaf are thus constrained to real anchored state.
            val recomputed = computeRootFromProof(msg.leaf, msg.proof);
            assert (recomputed == anchoredRoot) throw ErrCode.BAD_INCLUSION_PROOF;

            val id = storage.nextDisputeId;
            storage.nextDisputeId = id + 1;
            storage
                .disputes
                .set(
                    id,
                    {
                        challenger: in.senderAddress,
                        epoch: msg.epoch,
                        leaf: msg.leaf,
                        bond: in.valueCoins,
                        status: 0,
                    },
                );
            storage.save();
        }

        AnchorResolveDispute => {
            var storage = lazy AnchorStorage.load();
            val cfg = storage.config.load();
            assert (in.senderAddress == cfg.verdictAuthority) throw ErrCode.NOT_VERDICT_AUTHORITY;

            val found = storage.disputes.get(msg.disputeId);
            assert (found.isFound) throw ErrCode.NO_SUCH_DISPUTE;
            var dispute = found.loadValue();
            // A1 [CRITICAL]: refund/payout exactly ONCE. Without this guard,
            // re-sending the same disputeId re-pays the bond and drains other
            // challengers' commingled bonds. Require the open (0) state, and set
            // the terminal status + persist BEFORE sending the bond out.
            assert (dispute.status == 0) throw ErrCode.DISPUTE_NOT_OPEN;

            if (msg.upheld) {
                // Challenge upheld: return the bond to the challenger (the actual
                // stake slash + challenger bounty is applied on the cheater's
                // StakeVault via the slasher path).
                dispute.status = 1;
            } else {
                // Frivolous challenge: forfeit the bond to the treasury.
                dispute.status = 2;
            }
            // Persist the terminal status FIRST (effects before interactions), so a
            // bounce / re-delivery cannot re-enter and double-pay.
            storage.disputes.set(msg.disputeId, dispute);
            storage.save();

            if (msg.upheld) {
                refundBond(dispute.challenger, dispute.bond, msg.disputeId);
            } else {
                refundBond(cfg.auth.load().treasury, dispute.bond, msg.disputeId);
            }
        }

        // Authority-gated IN-PLACE code upgrade (§12.1). Replaces the CODE via
        // TVM `SETCODE` (postponed to after this run) at a STABLE address,
        // preserving the anchored epoch chain + open disputes, so the
        // anchor/dispute logic can evolve without orphaning history at a new
        // address. D2: gated to `upgradeAuthority`, a DISTINCT authority from the
        // dispute `verdictAuthority`, so a compromised dispute-resolver key cannot
        // also swap the contract code (separation of duties; meant to be a
        // multisig). `codeVersion` is bumped by the contract.
        AnchorUpgradeCode => {
            var storage = lazy AnchorStorage.load();
            val cfg = storage.config.load();
            assert (in.senderAddress == cfg.auth.load().upgradeAuthority) throw ErrCode.UPGRADE_NOT_AUTHORITY;
            contract.setCodePostponed(msg.newCode);
            storage.codeVersion += 1;
            storage.save();
        }

        else => {
            assert (in.body.isEmpty()) throw ErrCode.INVALID_OP;
        }
    }
}

// A1 bounce-safety: send the bond BOUNCEABLE with an op-tagged body so a failed
// delivery returns the funds here AND lets `onBouncedMessage` re-open the dispute.
// `Only256BitsOfBody` keeps the bounce cheap while preserving op + disputeId in
// the first 256 bounced bits. NOT IGNORE_ERRORS: we want a genuine bounce on
// failure (so accounting can be restored), not a silent drop.
fun refundBond(to: address, amount: coins, disputeId: int) {
    val m = createMessage({
        bounce: BounceMode.Only256BitsOfBody,
        dest: to,
        value: amount,
        body: AnchorBondRefund { disputeId: disputeId as uint32 },
    });
    m.send(SEND_MODE_PAY_FEES_SEPARATELY);
}

// ---------------------------------------------------------------------------
// Getters
// ---------------------------------------------------------------------------

get fun get_anchor_state(): AnchorState {
    val storage = lazy AnchorStorage.load();
    return {
        currentEpoch: storage.currentEpoch,
        lastRoot: storage.lastRoot,
        nextDisputeId: storage.nextDisputeId,
    };
}

// Monotonic CODE version/seqno — bumped on every successful in-place
// `upgrade_code` (§12.1). 0 = original deployed code. The anchor's code can be
// upgraded at a STABLE address (TVM SETCODE), so the anchored epoch chain is
// never orphaned by a logic change.
get fun get_code_version(): int {
    val storage = lazy AnchorStorage.load();
    return storage.codeVersion;
}

get fun get_dispute(disputeId: int): DisputeInfo? {
    val storage = lazy AnchorStorage.load();
    val found = storage.disputes.get(disputeId as uint32);
    if (!found.isFound) {
        return null;
    }
    return found.loadValue();
}

// Pure inclusion verifier (also used by tests): does `leaf` + `proof` reproduce
// `root`?
get fun verify_inclusion(leaf: int, root: int, proof: Cell<MerkleStep>?): bool {
    return computeRootFromProof(leaf, proof) == root;
}

get fun compute_root(leaf: int, proof: Cell<MerkleStep>?): int {
    return computeRootFromProof(leaf, proof);
}

// Storage + messages for the record-anchor / dispute contract.
// See BLOCKCHAIN_ECONOMICS §7 (hybrid records: off-chain receipts batched into a
// per-epoch Merkle tree, only the ROOT anchored on-chain), §7.2 (permissionless
// keepers + stake-weighted acceptance, chained roots via prev_root) and §11
// (optimistic settlement + bonded fraud proofs).
//
// Hash domain note (ALIGNED, end-to-end): the off-chain epoch tree and this
// on-chain verifier use the SAME internal-node hash so a proof built off-chain
// reproduces the anchored root here. A raw leaf is a BLAKE3(canonical JobRecord)
// 256-bit commitment (Rust side, p2p-settlement::types::JobRecord::leaf); before
// it is folded it is DOMAIN-SEPARATED via `hashLeaf` below — the cell
// representation hash of a ref-less cell holding one 256-bit int,
// `sha256(0x00 0x40 ‖ leaf)` (the A7 second-preimage fix, mirrored by the Rust
// `hash_leaf`), so a leaf value can never equal an interior node. Each parent is
// the TON cell
// representation hash of an ordinary ref-less cell holding `left ‖ right` (two
// 256-bit big-endian ints) — `hashPair` below. The Rust side reproduces this as
// `sha256(0x00 0x80 ‖ left ‖ right)` (see crates/settlement/src/merkle.rs); the
// `00 80` prefix is the cell descriptor for 512 byte-aligned data bits. `dir = 0`
// keeps the running accumulator on the LEFT (sibling on the right) and `dir = 1`
// on the right, matching the off-chain `(sibling_is_left, sibling)` proof order.

import "common"

const OP_ANCHOR_SUBMIT = 0x414e_4301
const OP_ANCHOR_DISPUTE = 0x414e_4302
const OP_ANCHOR_VERDICT = 0x414e_4303
const OP_ANCHOR_UPGRADE_CODE = 0x414e_4304 // "ANC" 04 — authority-gated in-place SETCODE upgrade
const OP_ANCHOR_BOND_REFUND = 0x414e_4305  // "ANC" 05 — bounce-safe bond refund (carries disputeId)

// One sibling on a Merkle inclusion path. `dir = 0`: sibling is the RIGHT node
// (current is the left child); `dir = 1`: sibling is the LEFT node.
struct MerkleStep {
    dir: uint1
    sibling: uint256
    next: Cell<MerkleStep>?
}

// Anchor authority addresses, grouped in a child cell so the root config cell
// stays within the 1023-bit budget (four addresses inline would overflow it).
struct AnchorAuthorities {
    treasury: address         // forfeited bonds / fees
    // A3: authorized anchor keeper. Root submission is gated to this address
    // (a configured keeper/authority — meant to be a keeper allowlist front or a
    // governance/oracle contract), NOT permissionless. `stakeWeight` in the
    // submission is still an unverified number, so the RESIDUAL ASSUMPTION is that
    // this keeper is honest about the aggregate stake backing a root; full
    // stake-proof aggregation is out of scope for a single contract. Restricting
    // who may submit removes the "anyone anchors a chosen root" attack.
    keeper: address
    // D2: distinct upgrade authority, separated from the verdictAuthority so a
    // single compromised dispute-resolver key cannot also swap the contract code.
    // Meant to be a multisig/governance contract.
    upgradeAuthority: address
}

struct AnchorConfig {
    minStakeWeight: coins     // stake-weighted threshold a submitted root must clear (§7.2)
    disputeBondMin: coins     // anti-griefing challenger bond (§13)
    verdictAuthority: address // committee/oracle that resolves disputes (§11)
    auth: Cell<AnchorAuthorities> // treasury + keeper + upgrade authority (child cell)
}

// status: 0 = open, 1 = upheld (challenger wins), 2 = rejected (bond forfeited)
struct DisputeInfo {
    challenger: address
    epoch: uint32
    leaf: uint256
    bond: coins
    status: uint2
}

struct AnchorStorage {
    currentEpoch: uint32 // last anchored epoch (0 = none yet)
    lastRoot: uint256    // last anchored root (the prev_root for the next epoch)
    nextDisputeId: uint32
    disputes: map<uint32, DisputeInfo>
    // A2: authoritative per-epoch anchored roots. A dispute's inclusion proof is
    // verified against the STORED root for `msg.epoch` (looked up here), NOT
    // against an attacker-supplied `claimedRoot`. Updated on every accepted
    // `AnchorSubmitRoot`. Unknown epochs are rejected (UNKNOWN_EPOCH), so a
    // dispute can only be opened against a root the contract actually anchored.
    roots: map<uint32, uint256>
    config: Cell<AnchorConfig>
    // Monotonic CODE version/seqno for in-place upgradeability (§12.1). Bumped by
    // the contract on every successful authority-gated `upgrade_code` (TVM
    // SETCODE), which swaps the CODE at a STABLE address without touching storage
    // — so the anchor/dispute logic can evolve (new getter/field, fixed verifier)
    // without forcing a redeploy that would orphan the anchored epoch chain.
    // Appended last (additive); 0 = original deployed code. Storage migrations
    // stay additive (append new fields LAST; older fields read unchanged).
    codeVersion: uint32
}

fun AnchorStorage.load(): AnchorStorage {
    return AnchorStorage.fromCell(contract.getData());
}

fun AnchorStorage.save(self) {
    contract.setData(self.toCell());
}

// Permissionless keeper submits the per-epoch root. `prevRoot` must chain to the
// stored `lastRoot`; `stakeWeight` is the aggregate staked weight backing this
// root (collected off-chain) and must clear the configured threshold.
struct (0x414e_4301) AnchorSubmitRoot {
    queryId: uint64
    epoch: uint32
    root: uint256
    prevRoot: uint256
    stakeWeight: coins
}

// Open a bonded dispute with a Merkle inclusion proof of the contested record.
// A2: `claimedRoot` is REMOVED — the proof is now verified against the root the
// contract has STORED for `epoch` (`storage.roots[epoch]`), so neither the root
// nor "which root" is attacker-controlled. The proof must fold (with the v2
// leaf-domain-separated `computeRootFromProof`) to that stored root.
struct (0x414e_4302) AnchorOpenDispute {
    queryId: uint64
    epoch: uint32
    leaf: uint256
    proof: Cell<MerkleStep>?
}

// Verdict from the authoritative committee/oracle.
struct (0x414e_4303) AnchorResolveDispute {
    queryId: uint64
    disputeId: uint32
    upheld: bool
}

// Outgoing bond-refund payload (A1 bounce-safety). The bond is returned to the
// challenger (upheld) or treasury (rejected) with this op-tagged body so that, if
// the recipient cannot accept it and the message BOUNCES, `onBouncedMessage` can
// recover the `disputeId` (from the first 256 bounced bits) and RE-OPEN the
// dispute (status → 0) — restoring accounting instead of silently losing the bond.
struct (0x414e_4305) AnchorBondRefund {
    disputeId: uint32
}

// Authority-gated IN-PLACE code upgrade (§12.1). Swaps this contract's CODE via
// TVM `SETCODE` (postponed to after this run) at a STABLE address, preserving the
// anchored epoch chain + open disputes. Gated to `config.verdictAuthority` (the
// same committee/oracle that resolves disputes — the anchor's governance
// authority); `newCode` is carried as a ^ref; `codeVersion` is bumped by the
// contract.
struct (0x414e_4304) AnchorUpgradeCode {
    queryId: uint64
    newCode: cell
}

struct AnchorState {
    currentEpoch: uint32
    lastRoot: uint256
    nextDisputeId: uint32
}

// ---------------------------------------------------------------------------
// Merkle helpers (TON cell-hash domain; self-consistent on-chain)
//
// MERKLE v2 (A7) — domain-separated leaf hashing (second-preimage fix). The leaf
// and the internal node now use DIFFERENT cell shapes, so a raw internal-node
// value can no longer be replayed as a leaf:
//   * INTERNAL node (UNCHANGED): hashPair(l, r) = repr-hash of a 0-ref cell with
//     TWO uint256  = sha256(0x00 0x80 ‖ l ‖ r). The `00 80` descriptor is an
//     ordinary ref-less cell with 512 byte-aligned data bits.
//   * LEAF (NEW): hashLeaf(x) = repr-hash of a 0-ref cell with ONE uint256
//     = sha256(0x00 0x40 ‖ x). The `00 40` descriptor is an ordinary ref-less
//     cell with 256 byte-aligned data bits (floor(256/8)=ceil(256/8)=32 → 0x40).
// The off-chain Rust builder (crates/settlement/src/merkle.rs) MUST byte-match
// these two constructions and build leaves as [hashLeaf(v0), hashLeaf(v1), ...],
// pairing with hashPair and PROMOTING a lone odd node UNCHANGED (no
// self-duplication) — so a promoted node contributes no proof step.
// ---------------------------------------------------------------------------

fun hashPair(left: int, right: int): int {
    return beginCell().storeUint(left, 256).storeUint(right, 256).endCell().hash();
}

// NEW (A7): domain-separated leaf hash. A 0-ref cell holding ONE uint256, whose
// representation hash is sha256(0x00 0x40 ‖ x). This is the second-preimage fix:
// the accumulator is seeded with hashLeaf(leaf), so the raw `leaf` integer is
// never itself a valid node value an attacker could substitute for an interior
// hash.
fun hashLeaf(x: int): int {
    return beginCell().storeUint(x, 256).endCell().hash();
}

// Fold a leaf up to the root along the supplied sibling path.
// A7: the accumulator is INITIALIZED to hashLeaf(leaf) (not the raw leaf).
// A4: the path is depth-capped at MAX_MERKLE_PROOF_DEPTH; an over-long
// attacker-supplied chain throws PROOF_TOO_DEEP instead of burning unbounded gas.
fun computeRootFromProof(leaf: int, proof: Cell<MerkleStep>?): int {
    var acc = hashLeaf(leaf);
    var cur = proof;
    var depth = 0;
    while (cur != null) {
        depth += 1;
        assert (depth <= MAX_MERKLE_PROOF_DEPTH) throw ErrCode.PROOF_TOO_DEEP;
        val step = cur.load();
        if (step.dir == 0) {
            acc = hashPair(acc, step.sibling);
        } else {
            acc = hashPair(step.sibling, acc);
        }
        cur = step.next;
    }
    return acc;
}

// A5: on-chain validation of the anchor config at deploy/upgrade time. Rejects a
// dispute bond minimum below the on-chain floor (a 0 / near-0 bond would enable
// griefing) so the bond can never be configured into uselessness.
fun validateAnchorConfig(cfg: AnchorConfig) {
    assert (cfg.disputeBondMin >= MIN_DISPUTE_BOND_FLOOR) throw ErrCode.BOND_FLOOR_TOO_LOW;
}

// Shared error codes, opcodes and constants for the duckdb-p2p settlement layer.
//
// These contracts implement the *paid* path of the economic layer described in
// `docs/BLOCKCHAIN_ECONOMICS.md`. Free jobs never touch any of this code — the
// requester runs them through the off-chain coordinator with the `NoopSettlement`
// path and there is zero on-chain interaction (see §8.2 "Free vs paid path").
//
// Design constraints honoured here (BLOCKCHAIN_ECONOMICS §1, §8):
//   * sharded per-node state (no global contract): one StakeVault per node,
//     one JobEscrow per job — never a single hot contract.
//   * non-custodial: release is governed entirely by contract code (quorum
//     result-hash, challenge window, unbonding cooldown), never a platform key.
//   * defensive TON style: explicit gas floors, bounce-safe, carry-value.
// ---------------------------------------------------------------------------
// Error codes — a typed `enum` (Tolk production guidance) instead of loose
// `const`s, so every `throw`/`assert` is checked against a single named set and
// a typo can't silently invent a new code. The backing type is `int32` (the TVM
// exit-code width); the numeric values are FROZEN — they are the contract ABI
// that off-chain code and tests assert against — so they are kept verbatim.
// Reference members as `ErrCode.NOT_OWNER`, etc.
// ---------------------------------------------------------------------------

enum ErrCode: int32 {
    // Jetton / receipt wallet
    NOT_OWNER = 132            // sender is not the contract owner
    NOT_FROM_MASTER = 133      // sender is not the jetton master (vault)
    NOT_VALID_WALLET = 134     // sender is not a legitimate sibling receipt wallet
    UNAUTHORIZED_BURN = 135    // burn notification not from the owner's wallet
    BALANCE_NEGATIVE = 136     // resulting balance would be negative
    NOT_ENOUGH_GAS = 137       // attached value too small to cover the operation
    RECEIPT_LOCKED = 138       // stake-receipt jetton is non-transferable (anti-exit)
    INVALID_OP = 0xffff        // unknown opcode

    // Stake vault
    NOT_SLASHER = 200          // sender is not the authorized slasher (dispute contract)
    NOTHING_TO_UNBOND = 201    // unbond requested but no eligible stake
    UNBOND_IN_PROGRESS = 202   // a prior unbond is still cooling down
    COOLDOWN_NOT_ELAPSED = 203 // withdraw before the unbonding cooldown finished
    NO_UNBONDING = 204         // withdraw with nothing in the unbonding bucket
    KEEPER_TOO_EARLY = 205     // keeper withdraw before the owner-grace window
    SLASH_EXCEEDS_STAKE = 206  // slash amount larger than slashable stake
    INVALID_SPLIT = 207        // slash split bps do not sum to 10000
    // Timelocked governance code upgrade (§8.6) — preserves the non-custodial
    // guarantee: an announced code swap can only be APPLIED after a delay >= the
    // unbonding window, so stakers can exit before any new code takes effect.
    NO_PENDING_UPGRADE = 208   // apply/cancel with nothing announced
    UPGRADE_TIMELOCK_ACTIVE = 209 // apply before the timelock delay elapsed
    UPGRADE_CODE_MISMATCH = 210 // applied code != the announced (hash-committed) code

    // Escrow
    ESCROW_NOT_FUNDED = 220    // escrow opened without the requester's max-bid B
    NOT_REQUESTER = 221        // settle/refund by someone other than the requester
    NOT_ARBITER = 222          // settle by someone other than the bound arbiter
    HASH_MISMATCH = 223        // provided result hash != the committed quorum hash
    ALREADY_SETTLED = 224      // escrow already released
    TIMEOUT_NOT_REACHED = 225  // refund-on-timeout before the deadline
    PAYOUT_EXCEEDS_ESCROW = 226 // requested payout exceeds the locked escrow B

    // Record anchor / dispute
    BAD_PREV_ROOT = 240        // submitted root does not chain to the stored prev_root
    EPOCH_REGRESSION = 241     // epoch did not advance monotonically
    INSUFFICIENT_ANCHOR_STAKE = 242 // keeper stake-weight below the acceptance threshold
    BAD_INCLUSION_PROOF = 243  // Merkle inclusion proof does not reproduce the root
    DISPUTE_BOND_TOO_LOW = 244 // challenger bond below the configured minimum
    NO_SUCH_DISPUTE = 245      // verdict for an unknown dispute id
    NOT_VERDICT_AUTHORITY = 246 // verdict from a non-authoritative source
    // --- Appended (security hardening; never renumber the frozen codes above) ---
    DISPUTE_NOT_OPEN = 247     // resolve a dispute that is not in the open (0) state (double-resolve)
    UNKNOWN_EPOCH = 248        // dispute references an epoch that was never anchored
    PROOF_TOO_DEEP = 249       // Merkle proof exceeds the max depth bound (gas-griefing guard)
    NOT_ANCHOR_KEEPER = 250    // root submitted by an address that is not the authorized keeper
    ZERO_ROOT = 251            // refuse anchoring an empty / all-zero root
    BOND_FLOOR_TOO_LOW = 252   // configured disputeBondMin is below the on-chain floor (> 0)

    // Global params (platform-wide config)
    NOT_ADMIN = 260            // sender is not the configured admin (or multisig)
    PARAMS_OUT_OF_BOUNDS = 261 // proposed params violate a §12 invariant

    // --- Appended: escrow / vault payout-authorization + bounce hardening ------
    NOT_OWNER_SIG = 280        // settle split not authorized by the fund-owner (requester) commitment
    SETTLE_POLICY_MISMATCH = 281 // settle payload does not match the requester's pre-committed policy hash
    TOO_MANY_PARTICIPANTS = 282  // participants map exceeds the on-chain payout bound (action/gas safety)
    UPGRADE_NOT_AUTHORITY = 283  // upgrade announced/applied by a non-upgrade-authority (separated from slasher)
    BAD_BOUNTY_BPS = 284         // keeperBountyBps out of [0, BPS_DENOM] (config sanity)
}

// ---------------------------------------------------------------------------
// Opcodes — keep TEP-74 standard values verbatim for ecosystem interop.
// ---------------------------------------------------------------------------

// TEP-74 jetton standard
const OP_JETTON_TRANSFER = 0x0f8a7ea5
const OP_JETTON_TRANSFER_INTERNAL = 0x178d4519
const OP_JETTON_NOTIFICATION = 0x7362d09c
const OP_JETTON_EXCESSES = 0xd53276db
const OP_JETTON_BURN = 0x595f07bc
const OP_JETTON_BURN_NOTIFICATION = 0x7bdd97de
const OP_PROVIDE_WALLET_ADDRESS = 0x2c76b973
const OP_TAKE_WALLET_ADDRESS = 0xd1735400

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MIN_TONS_FOR_STORAGE = ton("0.05")
const BPS_DENOM = 10000 // basis-points denominator for splits/fractions

// Status bit flags for the stake-receipt wallet.
const RECEIPT_STATUS_LOCKED = 1 // bit 0: outgoing transfers locked (default)

// Max Merkle inclusion-proof depth the on-chain verifier will walk before
// aborting (A4: an attacker-supplied proof chain is otherwise unbounded → gas
// griefing). 32 levels = up to 2^32 leaves per epoch, far beyond any realistic
// epoch batch, so this never rejects an honest proof.
const MAX_MERKLE_PROOF_DEPTH = 32

// On-chain floor for the dispute bond minimum (A5): a config that sets
// disputeBondMin below this is rejected at deploy/validate time so near-zero-bond
// griefing is impossible. 0.01 TON is a token but non-trivial anti-spam cost.
const MIN_DISPUTE_BOND_FLOOR = ton("0.01")

// Upper bound on the number of agreeing non-winners paid in a single settle
// action phase (B4): bounding the participants map keeps the settle within the
// TVM action/gas limit so a payout can never be partial. 32 covers the realistic
// committee size (N_max=10) with wide headroom.
const MAX_SETTLE_PARTICIPANTS = 32
